<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_admin_restrictions() { if ( ! current_user_can( 'sd_manage_member_restrictions' ) ) { wp_die( esc_html__( 'You are not allowed to view this page.', 'social-discovery-core' ) ); } global $wpdb; $t = sd_core_table_names(); $rows = $wpdb->get_results( "SELECT * FROM {$t['restrictions']} WHERE active=1 ORDER BY id DESC LIMIT 50" ); ?><div class="wrap"><h1><?php esc_html_e( 'Active Restrictions', 'social-discovery-core' ); ?></h1><table class="widefat striped"><thead><tr><th>User</th><th>Type</th><th>Reason</th><th>Applied</th><th>Expires</th></tr></thead><tbody><?php if ( empty( $rows ) ) : ?><tr><td colspan="5"><?php esc_html_e( 'No active restrictions.', 'social-discovery-core' ); ?></td></tr><?php else : foreach ( $rows as $row ) : $user = get_userdata( $row->user_id ); ?><tr><td><?php echo esc_html( $user ? $user->display_name : __( 'Deleted user', 'social-discovery-core' ) ); ?></td><td><?php echo esc_html( $row->restriction_type ); ?></td><td><?php echo esc_html( $row->reason ); ?></td><td><?php echo esc_html( $row->starts_at ); ?></td><td><?php echo esc_html( $row->expires_at ?: __( 'Until removed', 'social-discovery-core' ) ); ?></td></tr><?php endforeach; endif; ?></tbody></table></div><?php }
